+}
+
+.time-box p {
+    font-size: 0.75rem;
+    text-transform: uppercase;
+    margin: 0;
+    opacity: 0.8;
+}
+
+/* Editorial */
+.editorial-grid {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 60px;
+    align-items: center;
+}
+
+.editorial-image img {
+    width: 100%;
