+    object-fit: cover;
+}
+
+.eyebrow {
+    font-size: 0.8rem;
+    font-weight: 600;
+    text-transform: uppercase;
+    letter-spacing: 0.1em;
+    color: var(--secondary-color);
+    display: block;
+    margin-bottom: 16px;
+}
+
+.editorial-text p {
