.header {
    padding: 20px 0;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background-color: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(8px);
    z-index: 100;
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 0.1em;
}

.nav-links {
    display: flex;
    gap: 32px;
}

.nav-links a {
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--secondary-color);
}

.nav-links a:hover {
    color: var(--primary-color);
}

.header-icons {
    display: flex;
    gap: 20px;
    align-items: center;
}

.cart-icon {
    position: relative;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background-color: var(--accent-color);
    color: var(--white);
    font-size: 0.7rem;
    font-weight: 600;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Hero Section */
.hero {
    height: 80vh;
    min-height: 500px;
    background-color: var(--background-light);
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 0 24px;
    background-image: url('https://images.unsplash.com/photo-1618220179428-22790b46a0eb?q=80&w=2070&auto=format&fit=crop');
    background-size: cover;
    background-position: center;
    position: relative;
}

.hero::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-color: rgba(0, 0, 0, 0.2);
}

.hero-content {
    position: relative;
    max-width: 600px;
    color: var(--white);
    z-index: 1;
}

.hero-content p {
    font-size: 1.125rem;
    margin-bottom: 32px;
    opacity: 0.9;
}

/* Featured Products */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 40px;
}

.view-all {
    font-size: 0.9rem;
    font-weight: 500;
    text-decoration: underline;
    text-underline-offset: 4px;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 40px 24px;
}

.product-image {
    position: relative;
    overflow: hidden;
    margin-bottom: 16px;
    background-color: var(--background-light);
    aspect-ratio: 4/5;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: 12px;
    left: 12px;
    background-color: var(--white);
    padding: 4px 10px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.product-info {
    position: relative;
}

.product-title {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: 4px;
}

.product-price {
    color: var(--secondary-color);
    font-size: 0.9rem;
}

.add-to-cart {
    position: absolute;
    bottom: 0;
    right: 0;
    background: none;
    border: none;
    font-family: var(--font-main);
    font-size: 0.9rem;
    font-weight: 500;
    text-decoration: underline;
    cursor: pointer;
    opacity: 0;
    transform: translateY(10px);
    transition: var(--transition);
}

.product-card:hover .add-to-cart {
    opacity: 1;
    transform: translateY(0);
}

