}

.deals-content p {
    margin-bottom: 40px;
    font-size: 1.1rem;
}

.countdown {
    display: flex;
    justify-content: center;
    gap: 20px;
    margin-bottom: 40px;
}

.time-box {
    background-color: rgba(255, 255, 255, 0.1);
